@startuml

class Well {
  + code : string
}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + yearOfInstallation : int
  + geographicalArea : string
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Area {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

Well "*" -- "*" Company : extraction
Well "1" -- "0..1" Area : locatedIn
Extraction "*" -- "1" Well : refersTo
Extraction "*" -- "1" Company : performedBy

@enduml

